-- TcheLab — Fase 1: corrige 9 parameter_schema cujo nome de chave não batia
-- com o que o script Python de fato lê (achado na auditoria de hiperparâmetros,
-- 2026-10-13). Substitui o schema inteiro (não merge) porque o antigo estava
-- errado e não deve sobreviver. Idempotente.
SET NAMES utf8mb4;

UPDATE techniques SET parameter_schema = '{"task": {"type": "string", "default": "regression", "enum": ["regression", "classification"], "description": "Tipo de tarefa."}, "cell": {"type": "string", "default": "lstm", "enum": ["lstm", "gru"], "description": "Tipo de célula recorrente."}, "units": {"type": "array", "items": {"type": "integer", "minimum": 1}, "default": [64], "description": "Número de unidades por camada recorrente — o comprimento da lista é o número de camadas ocultas (ex: [64, 32] = 2 camadas)."}, "dense_units": {"type": "array", "items": {"type": "integer", "minimum": 1}, "default": [32], "description": "Unidades das camadas densas finais, após a parte recorrente."}, "dropout": {"type": "number", "default": 0.0, "minimum": 0, "maximum": 0.9, "description": "Taxa de dropout aplicada nas camadas recorrentes."}, "epochs": {"type": "integer", "default": 50, "minimum": 1, "description": "Número de épocas de treino."}, "batch_size": {"type": "integer", "default": 32, "minimum": 1, "description": "Tamanho do lote de treino."}, "learning_rate": {"type": "number", "default": 0.001, "minimum": 1e-07, "description": "Taxa de aprendizado do otimizador."}}' WHERE slug = 'rnn';
UPDATE techniques SET parameter_schema = '{"ranks": {"type": "array", "items": {"type": "integer", "minimum": 1}, "default": [2, 2, 2], "description": "Rank (número de componentes) em cada um dos 3 modos do tensor — deve ter exatamente 3 valores."}, "n_iter_max": {"type": "integer", "default": 100, "minimum": 1, "description": "Número máximo de iterações do algoritmo de otimização."}, "tol": {"type": "number", "default": 1e-08, "minimum": 0, "description": "Tolerância de convergência."}}' WHERE slug = 'tucker3';
UPDATE techniques SET parameter_schema = '{"n_components": {"type": "integer", "default": null, "minimum": 1, "description": "Número de componentes principais a reter. Deixe em branco para manter todos."}, "center": {"type": "boolean", "default": true, "description": "Centrar os dados na média antes de decompor (recomendado quase sempre)."}, "scale": {"type": "boolean", "default": false, "description": "Escalar cada variável pelo desvio padrão antes de decompor (autoscaling)."}}' WHERE slug = 'pca';
UPDATE techniques SET parameter_schema = '{"n_components": {"type": "integer", "default": 5, "minimum": 1, "description": "Número de variáveis latentes (componentes PLS)."}, "scale": {"type": "boolean", "default": false, "description": "Escalar X e Y antes do ajuste."}}' WHERE slug = 'pls';
UPDATE techniques SET parameter_schema = '{"n_components": {"type": "integer", "default": 2, "minimum": 1, "description": "Número de variáveis latentes (componentes PLS)."}, "threshold": {"type": "number", "default": 0.5, "minimum": 0, "maximum": 1, "description": "Limiar de decisão sobre a resposta dummy para atribuir a classe."}}' WHERE slug = 'pls_da';
UPDATE techniques SET parameter_schema = '{"n_estimators": {"type": "integer", "default": 100, "minimum": 1, "description": "Número de árvores na floresta."}, "max_depth": {"type": "integer", "default": null, "minimum": 1, "description": "Profundidade máxima de cada árvore. Deixe em branco para sem limite."}, "min_samples_split": {"type": "integer", "default": 2, "minimum": 2, "description": "Número mínimo de amostras para dividir um nó interno."}, "random_state": {"type": "integer", "default": 42, "description": "Semente aleatória, para resultados reprodutíveis."}}' WHERE slug = 'random_forest';
UPDATE techniques SET parameter_schema = '{"rank": {"type": "integer", "default": 2, "minimum": 1, "description": "Número de componentes (fatores) da decomposição trilinear."}, "n_iter_max": {"type": "integer", "default": 200, "minimum": 1, "description": "Número máximo de iterações do ALS."}, "tol": {"type": "number", "default": 1e-08, "minimum": 0, "description": "Tolerância de convergência."}, "random_state": {"type": "integer", "default": 42, "description": "Semente aleatória para a inicialização."}, "non_negative": {"type": "boolean", "default": false, "description": "Restringir os fatores a valores não-negativos (Non-negative PARAFAC)."}, "normalize_factors": {"type": "boolean", "default": true, "description": "Normalizar os fatores (só se non_negative=false)."}}' WHERE slug = 'parafac';
UPDATE techniques SET parameter_schema = '{"method": {"type": "string", "default": "pls", "enum": ["pls", "ridge", "lda", "rf_reg", "rf_cls"], "description": "Modelo a validar."}, "cv_type": {"type": "string", "default": "kfold", "enum": ["kfold", "loo", "montecarlo"], "description": "Estratégia de validação cruzada."}, "n_folds": {"type": "integer", "default": 5, "minimum": 2, "description": "Número de folds (usado quando cv_type=kfold)."}, "n_iter": {"type": "integer", "default": 20, "minimum": 1, "description": "Número de repetições (usado quando cv_type=montecarlo)."}, "test_size": {"type": "number", "default": 0.2, "minimum": 0.05, "maximum": 0.9, "description": "Fração de teste em cada repetição Monte Carlo."}}' WHERE slug = 'cross_validation';
UPDATE techniques SET parameter_schema = '{"window_length": {"type": "integer", "default": 11, "minimum": 3, "description": "Tamanho da janela — deve ser ímpar e maior que polyorder."}, "polyorder": {"type": "integer", "default": 2, "minimum": 1, "description": "Grau do polinômio ajustado em cada janela."}, "deriv": {"type": "integer", "default": 0, "minimum": 0, "maximum": 2, "description": "Ordem da derivada: 0=suavização, 1=1ª derivada, 2=2ª derivada."}, "spectral_axis": {"type": "integer", "default": 1, "description": "Eixo espectral (ao longo do qual o filtro é aplicado)."}}' WHERE slug = 'savitzky_golay';
